import{_ as t,o as a,c as n,ag as r}from"./chunks/framework.DTisvaUJ.js";const m=JSON.parse('{"title":"Supported languages and practical limitations","description":"Supported translation languages and quality cautions, based on measured Azure, PLaMo and TranslateGemma outputs.","frontmatter":{"description":"Supported translation languages and quality cautions, based on measured Azure, PLaMo and TranslateGemma outputs.","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/en/compare/translation/review"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"property":"og:title","content":"Supported languages and practical limitations | Mutelink"}],["meta",{"property":"og:description","content":"Supported translation languages and quality cautions, based on measured Azure, PLaMo and TranslateGemma outputs."}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/en/compare/translation/review"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"property":"og:image:width","content":"1400"}],["meta",{"property":"og:image:height","content":"547"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Supported languages and practical limitations | Mutelink"}],["meta",{"name":"twitter:description","content":"Supported translation languages and quality cautions, based on measured Azure, PLaMo and TranslateGemma outputs."}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/home-banner.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/compare/translation/review"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/compare/translation/review"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/compare/translation/review"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/compare/translation/review"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/compare/translation/review"}]]},"headers":[],"relativePath":"en/compare/translation/review.md","filePath":"en/compare/translation/review.md"}'),o={name:"en/compare/translation/review.md"};function i(s,e,l,d,u,h){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="対応表の見直しと、実用性の注意" tabindex="-1">Supported languages and practical limitations <a class="header-anchor" href="#対応表の見直しと、実用性の注意" aria-label="Permalink to &quot;Supported languages and practical limitations {#対応表の見直しと、実用性の注意}&quot;">​</a></h1><p><a href="./../translation">Comparison overview</a></p><h2 id="判断の範囲" tabindex="-1">Scope of the decision <a class="header-anchor" href="#判断の範囲" aria-label="Permalink to &quot;Scope of the decision {#判断の範囲}&quot;">​</a></h2><p>All 5,040 requests succeeded with non-empty text, but success does not establish language support or quality. These decisions concern generation in the requested language, not native-speaker approval of every output’s meaning or fluency. Raw outputs are available on each language page.</p><h2 id="translategemmaで復帰する3言語" tabindex="-1">Three languages restored for TranslateGemma <a class="header-anchor" href="#translategemmaで復帰する3言語" aria-label="Permalink to &quot;Three languages restored for TranslateGemma {#translategemmaで復帰する3言語}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Language</th><th>EN→X chrF</th><th>X→EN chrF</th><th>Observation and decision</th></tr></thead><tbody><tr><td><a href="./zh-hant">Traditional Chinese</a></td><td>46.2</td><td>71.5</td><td>30/30 both ways. No representative Simplified-only characters appeared in 30 EN→Traditional Chinese outputs; requested script was followed.</td></tr><tr><td><a href="./ms">Malay</a></td><td>67.2</td><td>72.6</td><td>30/30 both ways; ms exists in the model template. Restored because it generates the requested language, but some meanings are reversed.</td></tr><tr><td><a href="./tl">Filipino</a></td><td>58.2</td><td>71.5</td><td>30/30 both ways; tl exists in the model template. Restored, but some VR terminology is mistranslated.</td></tr></tbody></table><h3 id="品質上の注意例" tabindex="-1">Examples requiring caution <a class="header-anchor" href="#品質上の注意例" aria-label="Permalink to &quot;Examples requiring caution {#品質上の注意例}&quot;">​</a></h3><ul><li>Gemma, Malay EN→X #10: “My microphone is broken” became <code>Mikrofon saya berfungsi dengan baik</code> (“My microphone works well”), reversing the key meaning. It generates Malay, but important content still needs checking.</li><li>Gemma, Filipino X→EN #9: entering a VRChat instance became <code>Now, I want to discuss this specific case with you.</code>, changing the meaning to discussing a case.</li><li>Measurements used <strong>TranslateGemma 4B Q4_K_M</strong>, not Gemini, and <strong>PLaMo 0.8B Q4_K_M</strong>. Do not generalize to other sizes.</li></ul><h2 id="plamoで除外を維持する9言語" tabindex="-1">Nine languages remain excluded from PLaMo <a class="header-anchor" href="#plamoで除外を維持する9言語" aria-label="Permalink to &quot;Nine languages remain excluded from PLaMo {#plamoで除外を維持する9言語}&quot;">​</a></h2><p>Even languages absent from the official 53-language list received 60 direct requests each, bypassing the app’s allowlist. Wrong/mixed-language forward outputs and untranslated reverse copies keep them excluded from this model. Low chrF alone was not the reason.</p><table tabindex="0"><thead><tr><th>Language</th><th>EN→X chrF</th><th>Untranslated X→EN copies/30</th><th>Actual EN→X #1 output (success does not guarantee the requested language)</th></tr></thead><tbody><tr><td><a href="./pt">pt</a></td><td>15.2</td><td>8/30</td><td>Hallo, a拾って好上好。</td></tr><tr><td><a href="./tr">tr</a></td><td>3.1</td><td>4/30</td><td>Hallo, சிறப்பாக அறிமுகமாகிறேன்.</td></tr><tr><td><a href="./sv">sv</a></td><td>15.6</td><td>8/30</td><td>Hallo, leuk om you kennis te maken.</td></tr><tr><td><a href="./da">da</a></td><td>1.8</td><td>19/30</td><td>नमस्ते, खुशी लाग्यो भेट भएकोमा।</td></tr><tr><td><a href="./fi">fi</a></td><td>11.5</td><td>10/30</td><td>Hallo, freundlich kennenzulernen.</td></tr><tr><td><a href="./cs">cs</a></td><td>11.0</td><td>0/30</td><td>Hallo, leuk je jeter.</td></tr><tr><td><a href="./el">el</a></td><td>2.2</td><td>10/30</td><td>Hallo, leuke jeter.</td></tr><tr><td><a href="./ro">ro</a></td><td>3.0</td><td>13/30</td><td>नमस्ते, खुश लինուँ भेटेकोमा।</td></tr><tr><td><a href="./uk">uk</a></td><td>18.8</td><td>0/30</td><td>Hallo, приятно познакомиться.</td></tr></tbody></table><p>PLaMo retains 19 existing languages plus English (20 total). Azure retains all 28 tested languages. TranslateGemma allows all 28 plus English. Compare quality within the same language and direction, not chrF across languages.</p><h2 id="検証データの由来" tabindex="-1">Data provenance <a class="header-anchor" href="#検証データの由来" aria-label="Permalink to &quot;Data provenance {#検証データの由来}&quot;">​</a></h2><p>References for the original 26 languages were AI-authored by Claude; Traditional Chinese and Filipino additions by Codex. None were native-speaker proofread. Full outputs support judgments beyond scores or “experimental” labels. Future native-speaker reviews should be separate annotations, preserving raw outputs.</p>',14)])])}const c=t(o,[["render",i]]);export{m as __pageData,c as default};
